def esc(s):
    s = escape(s).replace("'", "\\'").replace('"', '\\"')
    if s[:1] in "@?":
        s = "\\" + s
    return s

for i, lang in enumerate(LANGS):
    folder = os.path.join(root, "values" + (f"-{lang}" if lang else ""))
    os.makedirs(folder, exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', "<!-- Najwa 1.4: generated, edit translations together across all languages. -->", "<resources>"]
    for key, values in S.items():
        assert len(values) == 7, key
        lines.append(f'    <string name="{key}">{esc(values[i])}</string>')
    for key, forms in PLURALS.items():
        lines.append(f'    <plurals name="{key}">')
        for q, text in forms[i].items():
            lines.append(f'        <item quantity="{q}">{esc(text)}</item>')
        lines.append("    </plurals>")
    lines.append("</resources>")
    open(os.path.join(folder, "release_14_strings.xml"), "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
print("wrote", len(S), "strings and", len(PLURALS), "plurals for", len(LANGS), "languages")
